#!/usr/bin/env bash
# PreToolUse (Edit|Write). An existing migration is never changed; a schema change is a new
# migration generated by drizzle-kit (drizzle/*.sql).
set -uo pipefail

path=$(jq -r '.tool_input.file_path // empty')

if [[ $path == */drizzle/*.sql || $path == drizzle/*.sql ]] && [ -e "$path" ]; then
  echo "BLOCKED (protect-migrations): '$path' already exists. Generate a new migration with drizzle-kit instead." >&2
  exit 2
fi

exit 0
